int venus_open ( struct super_block * sb , struct CodaFid * fid , int flags , struct file * * fh ) { union inputArgs * inp ; union outputArgs * outp ; int insize , outsize , error ; insize = SIZE ( open_by_fd ) ; UPARG ( CODA_OPEN_BY_FD ) ; inp -> coda_open_by_fd . VFid = * fid ; inp -> coda_open_by_fd . flags = flags ; if ( ! error ) { * fh = outp -> coda_open_by_fd . fh ; } CODA_FREE ( inp , insize ) ; return error ; } 